CREATE TABLE "__mistri_tenant_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1),
  app_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL
);
CREATE TABLE "__mistri_tenant_tenant" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'suspended', 'closed')),
  version TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('tenant', 'platform')),
  CHECK ((kind = 'platform') = (id = '@platform'))
);
CREATE TABLE "__mistri_tenant_membership" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  tenant_id TEXT COLLATE BINARY NOT NULL REFERENCES "__mistri_tenant_tenant" (id) ON DELETE RESTRICT,
  account_id TEXT COLLATE BINARY NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'revoked', 'invited')),
  version TEXT NOT NULL,
  roles_json TEXT NOT NULL CHECK (json_valid(roles_json) AND length(CAST(roles_json AS BLOB)) <= 262144),
  valid_until INTEGER NOT NULL CHECK (valid_until >= 0 AND valid_until <= 9007199254740991),
  kind TEXT NOT NULL CHECK (kind IN ('member', 'support')),
  parent_id TEXT COLLATE BINARY REFERENCES "__mistri_tenant_membership" (id) ON DELETE RESTRICT,
  parent_version TEXT,
  platform_version TEXT,
  CHECK ((kind = 'support') = (parent_id IS NOT NULL AND parent_version IS NOT NULL AND platform_version IS NOT NULL)),
  CHECK (kind = 'member' OR status IN ('active', 'revoked'))
);
CREATE UNIQUE INDEX "__mistri_tenant_live_membership" ON "__mistri_tenant_membership" (tenant_id, account_id) WHERE status != 'revoked' AND kind = 'member';
CREATE UNIQUE INDEX "__mistri_tenant_live_support" ON "__mistri_tenant_membership" (account_id) WHERE kind = 'support' AND status = 'active';
CREATE UNIQUE INDEX "__mistri_tenant_platform" ON "__mistri_tenant_tenant" (kind) WHERE kind = 'platform';
